-- ---------------------------------------------------------------------------
-- A saved, scheduled job source: where to read, how (strategy + site profile), which fields, and how often; runs feed job_postings.
create table careercloud.job_source_monitors (
  id                     text primary key check (id ~ '^jmon_[0-9a-f]{32}$'),
  workspace_id           uuid not null references careercloud.workspaces (id) on delete cascade,
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now(),
  created_by             uuid,
  version                integer not null default 1,
  name                   text not null check (char_length(name) <= 200),
  source_url             text not null check (char_length(source_url) <= 2048),
  source_name            text not null check (char_length(source_name) <= 200),
  source_type            text not null default 'job_board' check (source_type in ('job_board', 'company_careers', 'ats_api', 'feed')),
  strategy               text not null default 'wad_turbo' check (strategy in ('wad_turbo', 'site_profile', 'ai_scraper', 'jobspy')),
  profile                text check (char_length(profile) <= 60),
  filters                jsonb not null default '{}'::jsonb,
  extraction_schema      jsonb not null default '[]'::jsonb,
  schedule               text not null default 'daily' check (schedule in ('daily', 'weekly', 'manual')),
  full_sweep_days        integer not null default 7 check (full_sweep_days >= 1 and full_sweep_days <= 90),
  close_after_missed     integer not null default 2 check (close_after_missed >= 1 and close_after_missed <= 10),
  incremental_stop_pages integer not null default 3 check (incremental_stop_pages >= 1 and incremental_stop_pages <= 50),
  max_pages_incremental  integer not null default 200 check (max_pages_incremental >= 1 and max_pages_incremental <= 100000),
  max_pages_full         integer not null default 20000 check (max_pages_full >= 1 and max_pages_full <= 100000),
  outputs                text[] not null default '{}'::text[],
  enabled                boolean not null default true,
  next_run_at            timestamptz,
  next_full_sweep_at     timestamptz,
  last_run_id            text check (char_length(last_run_id) <= 40),
  last_run_at            timestamptz,
  last_run_status        text check (char_length(last_run_status) <= 40),
  last_full_sweep_at     timestamptz,
  last_result            jsonb not null default '{}'::jsonb,
  total_jobs             integer not null default 0 check (total_jobs >= 0)
);

