-- One execution of a job source monitor (incremental or full sweep) with its counts and a resumable checkpoint.
create table careercloud.job_monitor_runs (
  id                     text primary key check (id ~ '^jmr_[0-9a-f]{32}$'),
  workspace_id           uuid not null references careercloud.workspaces (id) on delete cascade,
  created_at             timestamptz not null default now(),
  updated_at             timestamptz not null default now(),
