  version                integer not null default 1,
  monitor_id             text not null check (char_length(monitor_id) <= 40),
  mode                   text not null default 'incremental' check (mode in ('incremental', 'full')),
  trigger                text not null default 'schedule' check (trigger in ('schedule', 'manual', 'api')),
  status                 text not null default 'queued' check (status in ('queued', 'running', 'completed', 'partial', 'failed', 'cancelled')),
  task_id                text check (char_length(task_id) <= 40),
  started_at             timestamptz,
  finished_at            timestamptz,
  pages                  integer not null default 0 check (pages >= 0),
  found                  integer not null default 0 check (found >= 0),
  new_count              integer not null default 0 check (new_count >= 0),
  changed_count          integer not null default 0 check (changed_count >= 0),
  unchanged_count        integer not null default 0 check (unchanged_count >= 0),
  reopened_count         integer not null default 0 check (reopened_count >= 0),
  closed_count           integer not null default 0 check (closed_count >= 0),
  rejected_count         integer not null default 0 check (rejected_count >= 0),
  error_count            integer not null default 0 check (error_count >= 0),
  warning_count          integer not null default 0 check (warning_count >= 0),
  request_count          integer not null default 0 check (request_count >= 0),
  duration_seconds       double precision check (duration_seconds >= 0),
  stop_reason            text check (char_length(stop_reason) <= 500),
  error                  text check (char_length(error) <= 2000),
  checkpoint             jsonb not null default '{}'::jsonb,
  notes                  jsonb not null default '[]'::jsonb
);

