-- A historical CSV/XLSX job file: detected headers, the confirmed column mapping, validation, and a resumable import into job_postings.
create table careercloud.job_imports (
  id                     text primary key check (id ~ '^jimp_[0-9a-f]{32}$'),
  workspace_id           uuid not null references careercloud.workspaces (id) on delete cascade,
  created_at             timestamptz not null default now(),
