  created_by             uuid,
  version                integer not null default 1,
  filename               text not null check (char_length(filename) <= 300),
  format                 text not null default 'csv' check (format in ('csv', 'xlsx')),
  storage_key            text not null check (char_length(storage_key) <= 500),
  size_bytes             bigint not null default 0 check (size_bytes >= 0),
  sheet                  text check (char_length(sheet) <= 200),
  headers                text[] not null default '{}'::text[],
  row_count              integer not null default 0 check (row_count >= 0),
  mapping                jsonb not null default '{}'::jsonb,
  default_source         text check (char_length(default_source) <= 200),
  status                 text not null default 'uploaded' check (status in ('uploaded', 'validated', 'importing', 'completed', 'failed', 'cancelled')),
  task_id                text check (char_length(task_id) <= 40),
  validation             jsonb not null default '{}'::jsonb,
